// Generated by ts-rs from the Rust types the socket carries: change those and run `cargo test -p p02-gateway contract`.

export type ActivationStatus = "active" | "disabled" | "blocked";

/**
 * The person's answer to a parked confirmation or a pairing request.
 */
export type Answer = "approved" | "denied";

/**
 * The person's answer, to a confirmation or a pairing request alike.
 */
export type AnswerBody = { decision: Answer, };

/**
 * What an answer to a parked confirmation came to. `expired`: the deadline
 * had passed, so the confirmation was settled cancelled instead; the
 * client is never the judge of the deadline.
 */
export type AnswerOutcome = { "status": "answered" } | { "status": "expired" } | { "status": "unknown" };

/**
 * What the target's own document holds for a field.
 */
export type Authored = { configured: boolean, value?: JsonValue, };

/**
 * Why a change was refused.
 */
export type ChangeRefusal = "conflict" | "invalid" | "unknown_character";

export type CharacterConnectorEntry = { characterId: Identifier, activation: RuntimeConfigSectionActivationShape, values: { [key in string]: JsonValue }, };

/**
 * Where a character's runtime stands. `reloading` is a pause: a
 * delivery sent meanwhile waits for it and lands on the same thread.
 */
export type CharacterRuntimeState = "starting" | "ready" | "reloading" | "stopping" | "stopped" | "failed";

/**
 * One installed character, as health reports her.
 */
export type CharacterSummary = { id: Identifier, displayName: SpeakerName, enabled: boolean, state: RosterState, 
/**
 * Why she failed, or what her start warned of.
 */
diagnostic?: string, 
/**
 * The latest background failure since she started.
 */
maintenance?: MaintenanceFailure, };

/**
 * What a client stamps on a line it carries: the surface it came from, or
 * the id it submitted the line under, which a repeat of the line reuses. An
 * ASCII letter or digit, then up to 63 ASCII letters, digits, `:`, `.`, `_`
 * or `-`.
 */
export type ClientStamp = string;

/**
 * What a finding is, in the one spelling clients read.
 */
export type Code = "runtime_config_read_failed" | "runtime_config_malformed_json" | "runtime_config_not_object" | "runtime_config_limit_exceeded" | "runtime_config_version_unsupported" | "runtime_config_unknown_top_level_field" | "runtime_config_project02_not_object" | "runtime_config_unknown_project02_field" | "runtime_config_plugins_not_object" | "runtime_config_connectors_not_object" | "runtime_config_unknown_plugin" | "runtime_config_unknown_connector" | "runtime_config_plugin_not_object" | "runtime_config_unknown_plugin_wrapper_field" | "runtime_config_boolean_invalid" | "runtime_config_plugin_config_not_object" | "runtime_config_unknown_plugin_config_field" | "runtime_config_string_invalid" | "runtime_config_role_model_provider_invalid" | "runtime_config_secret_value_invalid" | "runtime_config_nvidia_base_url_invalid" | "runtime_config_context_window_tokens_invalid" | "runtime_config_value_type_invalid" | "runtime_config_required_value_missing" | "runtime_config_required_secret_missing" | "runtime_config_authored_outside_scope" | "character_package_plugin_config_invalid" | "default_memory_provider_unavailable" | "default_memory_provider_not_memory_provider" | "ambiguous_memory_provider_selection" | "character_required_plugin_missing" | "character_required_plugin_disabled" | "character_recommended_plugin_missing" | "character_recommended_plugin_disabled";

/**
 * One change to one document, bound to the fingerprint its author read.
 */
export type ConfigChange = { target: ConfigTarget, expectedFingerprint: string, operation: Operation, };

/**
 * What came of a change. `Applied` means the document is on disk, under
 * the fingerprint it now has; `Refused` is the change itself, and
 * `Failed` a write that could not be made, either leaving every document
 * as it was.
 */
export type ConfigChangeOutcome = { "status": "applied", fingerprint: Fingerprint, } | { "status": "refused", reason: ChangeRefusal, message: string, } | { "status": "failed", message: string, };

export type ConfigHealth = { diagnostics: ReadonlyArray<RuntimeConfigDiagnostic>, };

/**
 * Whose settings a view reads or a change writes: the home's, or one
 * character's.
 */
export type ConfigTarget = { "scope": "global" } | { "scope": "character", characterId: string, };

/**
 * The kind of value a config field holds. Whether it holds a
 * credential is the field's `secret` flag alone to say.
 */
export type ConfigValueType = "string" | "number" | "boolean" | "object" | "array" | "path" | "enum";

/**
 * What a settings screen renders: the fingerprint a change must present,
 * the diagnostics, and the host's fields and every section the target may
 * set, all in one field shape. A target whose settings cannot be resolved
 * is refused with the reason, never shown as blank fields.
 */
export type ConfigView = { "status": "ok", fingerprint: Fingerprint, diagnostics: ReadonlyArray<RuntimeConfigDiagnostic>, project02: ReadonlyArray<RuntimeConfigFieldInspectShape>, sections: ReadonlyArray<RuntimeConfigSectionInspectShape>, } | { "status": "refused", reason: ViewRefusal, message: string, };

export type ConfirmationCancelReason = "expired" | "stopped";

/**
 * A parked confirmation's id: a fresh UUID, unique across the daemon, by
 * which any surface answers it.
 */
export type ConfirmationId = string;

/**
 * What the person is asked about: the plugin and tool whose call it is,
 * what the tool says it does, and what the call would do.
 */
export type ConfirmationQuestion = { pluginId: Identifier, toolName: Identifier, summary: string, preview: { [key in string]: JsonValue }, };

/**
 * How a confirmation ended: with the person's answer, or cancelled and
 * why.
 */
export type ConfirmationSettlement = { "decision": "approved" } | { "decision": "denied" } | { "decision": "cancelled", reason: ConfirmationCancelReason, };

/**
 * A connector's section for one target: its activation, and each field
 * that has a value it takes for that target, the home's fields reaching
 * every character's entry.
 */
export type ConnectorConfigEntry = { activation: RuntimeConfigSectionActivationShape, values: { [key in string]: JsonValue }, };

/**
 * What a connector runs on: an entry for the home and one for each
 * installed character that is switched on, in roster order, each with
 * its section's activation and, while that is active, the values in
 * effect for it, secrets in the clear. The home's switch is a default,
 * not a master switch: each entry is judged by its own.
 */
export type ConnectorConfigView = { "status": "ok", connectorId: Identifier, home: ConnectorConfigEntry, characters: ReadonlyArray<CharacterConnectorEntry>, } | { "status": "refused", reason: ConnectorRefusal, message: string, };

/**
 * Whether a process of a built-in connector is on the event stream now.
 */
export type ConnectorPresence = { id: Identifier, connected: boolean, };

export type ConnectorRefusal = "unknown_connector" | "config_unloadable";

/**
 * A conversation: an ASCII letter or digit, then up to 55 ASCII letters,
 * digits, `_` or `-`. It holds no `.`, which is what parts it from the
 * segment number in the id of each of its sessions, and its length leaves
 * that id room for the segment within the 64 characters a tool admits.
 */
export type ConversationId = string;

/**
 * The value in effect: authored in a document, `config`; the declared
 * default, `default`; or none, `missing`. A refused value is in effect
 * unresolved, its value shown unless it is a secret's.
 */
export type EffectiveView = { name: Identifier, secret: boolean, source: ValueSource, resolved: boolean, value?: JsonValue, };

/**
 * A value's identity, comparable without the value: `sha256:` and the
 * lowercase hex SHA-256 of its [`canonical_json`].
 */
export type Fingerprint = string;

/**
 * The one shape every transport refusal takes; a verb's outcome never
 * uses it.
 */
export type GatewayErrorBody = { error: Refusal, };

/**
 * What every surface hears.
 */
export type GatewayEvent = { "kind": "turn_progress", characterId: Identifier, conversationId: ConversationId, progress: TurnProgress, } | { "kind": "turn_completed", characterId: Identifier, conversationId: ConversationId, source: ClientStamp, clientMessageId: ClientStamp, status: TurnStatus, committed: boolean, reason?: string, message?: string, } | { "kind": "confirmation_requested" } & PendingConfirmation | { "kind": "confirmation_settled", characterId: Identifier, id: ConfirmationId, } & ({ "decision": "approved" } | { "decision": "denied" } | { "decision": "cancelled", reason: ConfirmationCancelReason, }) | { "kind": "pairing_requested" } & PairingRequest | { "kind": "pairing_settled", connectorId: Identifier, code: string, subject: PairingSubject, decision: PairingDecision, } | { "kind": "state_changed", characterId: Identifier, state: CharacterRuntimeState, 
/**
 * Present when a failure caused the change.
 */
message?: string, } | { "kind": "health_changed", health: GatewayHealth, } | { "kind": "maintenance_failed", characterId: Identifier, at: Timestamp, message: string, };

/**
 * The daemon's whole state in one read.
 */
export type GatewayHealth = { protocolVersion: 7, homeRoot: string, 
/**
 * What the home's settings document says of itself.
 */
config: ConfigHealth, 
/**
 * The packages discovery could not publish, which the roster lacks.
 */
packages: PackagesHealth, characters: ReadonlyArray<CharacterSummary>, connectors: ReadonlyArray<ConnectorPresence>, };

/**
 * A line from one participant into one conversation, with the two stamps
 * its client puts on it: which surface carried it, and the id a repeat of
 * the same submission reuses.
 */
export type GatewayMessage = { conversationId: Short, senderId: Short, text: Text, source: ClientStamp, clientMessageId: ClientStamp, };

/**
 * The first frame of a stream that cannot be caught up: the state every
 * later frame moves on from.
 */
export type GatewayReady = { protocolVersion: 7, health: GatewayHealth, confirmations: ReadonlyArray<PendingConfirmation>, pairings: ReadonlyArray<PairingRequest>, turns: ReadonlyArray<RunningTurn>, };

/**
 * Why a line was refused before any turn ran.
 */
export type GatewayRefusalReason = "unknown_character" | "unknown_conversation" | "conversation_unreadable" | "sender_not_supported" | "character_unavailable" | "invalid_message" | "duplicate_submission";

/**
 * A committed message as a client renders it.
 */
export type GatewayVisibleMessage = { messageId: MessageId, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, };

/**
 * A committed message as the scrollback shows it, with the stamps its
 * client put on the person's line and when it was committed.
 */
export type HistoryMessage = { messageId: MessageId, role: VisibleMessageRole, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, committedAt: Timestamp, source?: ClientStamp, clientMessageId?: ClientStamp, };

/**
 * One page of a conversation's scrollback, chronological within the page;
 * `earlier` is the cursor of the page before it, while older messages
 * exist.
 */
export type HistoryOutcome = { "status": "ok", conversationId: ConversationId, characterId: Identifier, messages: ReadonlyArray<HistoryMessage>, earlier?: string, } | { "status": "refused", reason: HistoryRefusal, message: string, } | { "status": "failed" } & StorageFailure;

export type HistoryRefusal = "unknown_conversation" | "invalid_page";

/**
 * A Project02 identifier: an ASCII letter, then up to 127 ASCII letters,
 * digits, `.`, `_` or `-`. Characters, plugins and tools are named by one.
 */
export type Identifier = string;

export type JsonValue = number | string | boolean | ReadonlyArray<JsonValue> | { [key in string]: JsonValue } | null;

/**
 * A background failure the conversation never sees: the plugins' work
 * after a turn's commit, a segment rotation that failed, which the next
 * turn plans again, or a closed segment's end hooks that did not finish.
 */
export type MaintenanceFailure = { at: Timestamp, message: string, };

/**
 * A message's place in its session: `<session id>:message-<n>`, numbered
 * from 1. Numbers climb but may skip, so a message's number is its order,
 * not a count.
 */
export type MessageId = string;

/**
 * The character whose thread with the person to open.
 */
export type OpenConversationBody = { characterId: Short, };

/**
 * What came of opening a character's thread with the person.
 */
export type OpenOutcome = { "status": "opened", conversationId: ConversationId, characterId: Identifier, 
/**
 * Who the caller is in the thread: the sender a delivery names.
 */
userParticipantId: Identifier, } | { "status": "refused", reason: OpenRefusal, message: string, } | { "status": "failed" } & StorageFailure;

export type OpenRefusal = "unknown_character" | "character_unavailable";

/**
 * What a change does: sets or unsets a host field, by its path
 * `project02.<name>`; switches a section on or off, or leaves it to the
 * document beneath when `enabled` is absent; or sets or unsets one field
 * of a section.
 */
export type Operation = { "kind": "set", path: string, value: JsonValue, } | { "kind": "unset", path: string, } | { "kind": "section_enabled", namespace: RuntimeConfigSectionNamespace, id: string, enabled?: boolean, } | { "kind": "section_field_set", namespace: RuntimeConfigSectionNamespace, id: string, field: string, value: JsonValue, } | { "kind": "section_field_unset", namespace: RuntimeConfigSectionNamespace, id: string, field: string, };

export type Origin = { "scope": "character", characterId: Identifier, path: string, };

/**
 * Where a package comes from: compiled in, or added by the person.
 */
export type PackageProvenance = "bundled" | "operator";

/**
 * A package discovery could not publish, and why, where.
 */
export type PackageReport = { 
/**
 * Always an error: the package is not in the roster.
 */
severity: Severity, code: string, message: string, path: string, provenance: PackageProvenance, 
/**
 * The folder the package was found in.
 */
characterId?: string, 
/**
 * The id its descriptor claims, when that is not its folder's.
 */
claimedCharacterId?: Identifier, };

export type PackagesHealth = { diagnostics: ReadonlyArray<PackageReport>, };

/**
 * How a pairing request ended: with the person's answer, or at its
 * deadline.
 */
export type PairingDecision = "approved" | "denied" | "expired";

export type PairingRefusal = "unknown_connector" | "config_unloadable" | "invalid_subject";

/**
 * An account a connector asks to let in, waiting for the person's answer
 * under a code any surface shows and answers by, until it expires.
 */
export type PairingRequest = { connectorId: Identifier, 
/**
 * Six digits, unique among the requests waiting.
 */
code: string, subject: PairingSubject, requestedAt: Timestamp, 
/**
 * When the request expires, in milliseconds since the Unix epoch.
 */
expiresAt: number, };

/**
 * The account a connector asks the person to let in.
 */
export type PairingRequestBody = { subject: PairingSubjectBody, };

/**
 * What came of a connector's request to let an account in. `paired`: the
 * home lets it in already, so nothing is asked.
 */
export type PairingRequestOutcome = { "status": "pending", request: PairingRequest, } | { "status": "paired" } | { "status": "refused", reason: PairingRefusal, message: string, };

/**
 * What an answer to a pairing request came to. `expired`: the deadline had
 * passed, so the request was settled expired instead, as a confirmation
 * is; `failed`: the approval could not be written, and the request waits
 * on.
 */
export type PairingSettleOutcome = { "status": "settled", decision: Answer, } | { "status": "expired" } | { "status": "unknown" } | { "status": "failed", message: string, };

/**
 * The account a pairing is for: the connector's own id for it, and the
 * name the person sees.
 */
export type PairingSubject = { id: ClientStamp, label: SpeakerName, };

/**
 * The account a pairing is for: its id a stamp, and its name within the
 * bound of a name a person goes by, which the daemon judges further.
 */
export type PairingSubjectBody = { id: ClientStamp, label: Short, };

/**
 * A parked confirmation, as the stream announced it and the list shows it.
 */
export type PendingConfirmation = { characterId: Identifier, id: ConfirmationId, request: ConfirmationQuestion, 
/**
 * When the confirmation expires, in milliseconds since the Unix epoch.
 */
deadlineAt: number, 
/**
 * The turn that raised it; none for a call raised outside any turn.
 */
turn?: TurnIdentity, };

/**
 * A transport refusal: its status, and the envelope's code and sentence.
 */
export type Refusal = { code: string, message: string, };

/**
 * Where an installed character stands as health reports her: her
 * runtime's state, or `not_started` until the daemon built it.
 */
export type RosterState = "not_started" | "starting" | "ready" | "reloading" | "stopping" | "stopped" | "failed";

/**
 * One open draft: the reply's text so far under its id.
 */
export type RunningDraft = { draftId: string, text: string, };

/**
 * A turn in progress, as the stream has told it so far: the submission it
 * runs for, its character, and each open draft's text.
 */
export type RunningTurn = { characterId: Identifier, conversationId: ConversationId, source: ClientStamp, clientMessageId: ClientStamp, drafts: ReadonlyArray<RunningDraft>, };

/**
 * A finding about the settings: its weight, its code, a sentence for a
 * person that never repeats a value, the place in the document, what it
 * concerns, the settings as a whole or one section, and, for a finding in
 * a character's overlay, whose.
 */
export type RuntimeConfigDiagnostic = { severity: Severity, code: Code, message: string, path?: string, origin?: Origin, } & ({ "scope": "global" } | { "scope": "section", namespace: RuntimeConfigSectionNamespace, id: string, field?: string, });

/**
 * One field as a screen shows it: its declaration, what the target's own
 * document holds for it, and the value in effect with where it comes
 * from, a secret's as `[redacted]`.
 */
export type RuntimeConfigFieldInspectShape = { name: Identifier, description: string, required: boolean, secret: boolean, valueType?: ConfigValueType, allowedValues?: ReadonlyArray<string>, agentMutable: boolean, reloadRequired: boolean, authored: Authored, effectiveSource: Source, effective: EffectiveView, };

/**
 * Whether a section runs, as its settings decide it, and why.
 */
export type RuntimeConfigSectionActivationShape = { enabled: boolean, status: ActivationStatus, reasons: ReadonlyArray<string>, };

/**
 * One section as a screen shows it.
 */
export type RuntimeConfigSectionInspectShape = { namespace: RuntimeConfigSectionNamespace, id: Identifier, displayName: string, version: string, enabled: boolean, 
/**
 * Which document decides `enabled`, or the declaration's default.
 */
enabledSource: Source, activation: RuntimeConfigSectionActivationShape, fields: ReadonlyArray<RuntimeConfigFieldInspectShape>, diagnostics: ReadonlyArray<RuntimeConfigDiagnostic>, 
/**
 * What a change to this section alone may present.
 */
fingerprint: Fingerprint, };

/**
 * The two stanzas of a document that hold declared sections by id. A
 * plugin and a connector may share an id: their sections never meet.
 */
export type RuntimeConfigSectionNamespace = "plugins" | "connectors";

/**
 * How much a finding weighs: an error stops what it concerns, a warning
 * only says so.
 */
export type Severity = "warning" | "error";

/**
 * A string of 1 to 128 characters, as an id is on the wire, and the name
 * an account goes by.
 */
export type Short = string;

/**
 * Where a value in effect comes from: its field's declared default, the
 * home's settings, or the character's own.
 */
export type Source = "default" | "global" | "character";

/**
 * The name a speaker goes by on a message: one line of at most 128
 * characters, without blank space at either end. It is set before a
 * colon in chat, which is why a line break is refused.
 */
export type SpeakerName = string;

/**
 * What an explicit start came to: `settled` says it ran, and the summary's
 * state says how it ended.
 */
export type StartOutcome = { "status": "settled", character: CharacterSummary, } | { "status": "refused", reason: StartRefusal, message: string, };

export type StartRefusal = "unknown_character" | "gateway_stopped";

/**
 * An ordinary failure of the home's storage, a full disk, a permission or
 * a damaged record, which the person is told and which is no bug.
 */
export type StorageFailure = { code: string, message: string, };

/**
 * A line's text: at least one character, and as long as any text of a
 * body may be.
 */
export type Text = string;

/**
 * A moment, in the one spelling every record uses: UTC to the
 * millisecond, `2026-06-15T00:00:00.000Z`. Text order is time order.
 */
export type Timestamp = string;

/**
 * How a call of a round came back: as its plugin answered, or refused.
 */
export type ToolCallStatus = "accepted" | "rejected";

/**
 * The submission a turn runs for, which any surface can tell as its own.
 */
export type TurnIdentity = { conversationId: ConversationId, source: ClientStamp, clientMessageId: ClientStamp, };

/**
 * What became of a delivered line.
 */
export type TurnOutcome = { "status": "completed", characterId: Identifier, conversationId: ConversationId, 
/**
 * What the turn committed, the person's line first.
 */
messages: ReadonlyArray<GatewayVisibleMessage>, } | { "status": "rejected", characterId: Identifier, conversationId: ConversationId, reason: string, message: string, committed: boolean, } | { "status": "refused", reason: GatewayRefusalReason, message: string, } | { "status": "failed", characterId: Identifier, conversationId: ConversationId, message: string, committed: boolean, };

/**
 * What a turn says as it goes, in order.
 */
export type TurnProgress = { "kind": "user_message", messageId: MessageId, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, source?: ClientStamp, clientMessageId?: ClientStamp, } | { "kind": "visible_reply", messageId: MessageId, speakerId: Identifier, speakerName: SpeakerName, text: VisibleText, 
/**
 * The draft this message replaces.
 */
draftId: string, } | { "kind": "reply_delta", draftId: string, text: string, } | { "kind": "reply_withdrawn", draftId: string, } | { "kind": "tool_calls_requested", round: number, toolNames: ReadonlyArray<Identifier>, } | { "kind": "tool_call_completed", round: number, status: ToolCallStatus, toolName: Identifier, };

/**
 * How a delivery ended, as the frame announcing it says: the status of
 * its outcome.
 */
export type TurnStatus = "completed" | "rejected" | "refused" | "failed";

export type ValueSource = "config" | "default" | "missing";

export type ViewRefusal = "unknown_character" | "config_unloadable";

/**
 * Which side of a conversation someone speaks for: a character, or the
 * person. A visible message carries its speaker's, and the two order as
 * they are spelled, characters first.
 */
export type VisibleMessageRole = "character" | "user";

/**
 * Text as a person sees it: line endings are `\n`, neither end is blank
 * space, and something is left.
 */
export type VisibleText = string;
